# join_with_and :: ['a', 'b', 'c']
def join_with_and(items):
    items = list(items)
    if len(items) == 0:
        return ''
    if len(items) == 1:
        return items[0]
    return ', '.join(items[:-1]) + ' and ' + items[-1]

if __name__ == '__main__':
    print(join_with_and(['a', 'b', 'c']))

